const uiChoice=localStorage.getItem('uiLanguage')||'auto';
function supportedUILanguage(value){
 const tag=String(value||'en').replaceAll('_','-').toLowerCase();
 if(tag==='pt'||tag.startsWith('pt-'))return 'pt-BR';
 if(tag==='zh'||tag==='zh-cn'||tag==='zh-sg'||tag.startsWith('zh-hans'))return 'zh-CN';
 if(tag.startsWith('zh-'))return 'en';
 const base=tag.split('-')[0];return UI_TEXT[base]?base:'en';
}
const detectedUI=supportedUILanguage(chrome.i18n?.getUILanguage?.()||navigator.language||'en');
const uiLang=UI_TEXT[uiChoice==='auto'?detectedUI:uiChoice]? (uiChoice==='auto'?detectedUI:uiChoice):'en';
function t(key){return UI_TEXT[uiLang][key]||UI_TEXT.en[key]||key;}
function localizeUI(){document.documentElement.lang=uiLang;document.documentElement.dir=['ar','fa'].includes(uiLang)?'rtl':'ltr';for(const e of document.querySelectorAll('[data-i18n]'))e.textContent=t(e.dataset.i18n);}
